    ('202609120001', 'policy', 'profiles.profile self or staff read', 'SELECT|{authenticated}|PERMISSIVE|((id = ( SELECT auth.uid() AS uid)) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
    ('202609120001', 'policy', 'profiles.profile self update', 'UPDATE|{authenticated}|PERMISSIVE|(id = ( SELECT auth.uid() AS uid))|(id = ( SELECT auth.uid() AS uid))'),
    ('202609120001', 'policy', 'user_roles.roles staff read', 'SELECT|{authenticated}|PERMISSIVE|((user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
    ('202609120001', 'policy', 'technician_profiles.technician visibility', 'SELECT|{authenticated}|PERMISSIVE|((user_id = ( SELECT auth.uid() AS uid)) OR (verification_status = ''APPROVED''::document_status) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
    ('202609120001', 'policy', 'technician_profiles.technician self update', 'UPDATE|{authenticated}|PERMISSIVE|(user_id = ( SELECT auth.uid() AS uid))|(user_id = ( SELECT auth.uid() AS uid))'),
    ('202609120001', 'policy', 'technician_documents.documents owner or staff', 'SELECT|{authenticated}|PERMISSIVE|((technician_id = ( SELECT auth.uid() AS uid)) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
    ('202609120001', 'policy', 'technician_documents.documents owner insert', 'INSERT|{authenticated}|PERMISSIVE||(technician_id = ( SELECT auth.uid() AS uid))'),
    ('202609120001', 'policy', 'service_regions.catalog public read regions', 'SELECT|{public}|PERMISSIVE|is_active|'),
    ('202609120001', 'policy', 'services.catalog public read services', 'SELECT|{public}|PERMISSIVE|is_active|'),
    ('202609120001', 'policy', 'service_areas.catalog public read areas', 'SELECT|{public}|PERMISSIVE|is_active|'),
    ('202609120001', 'policy', 'orders.orders customer tech staff read', 'SELECT|{authenticated}|PERMISSIVE|((customer_id = ( SELECT auth.uid() AS uid)) OR ( SELECT security.is_assigned_technician(orders.id) AS is_assigned_technician) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
    ('202609120001', 'policy', 'orders.orders customer insert', 'INSERT|{authenticated}|PERMISSIVE||((customer_id = ( SELECT auth.uid() AS uid)) AND (status = ''REQUESTED''::order_status))'),
