    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_obligation_type_check', 'c|CHECK ((obligation_type = ANY (ARRAY[''HELPER_PAYOUT''::text, ''REFERRAL_PAYOUT''::text, ''REFUND''::text])))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_rail_check', 'c|CHECK ((rail ~ ''^[A-Z0-9_]{2,40}$''::text))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_provider_check', 'c|CHECK ((provider ~ ''^[A-Z0-9_]{2,40}$''::text))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_network_check', 'c|CHECK (((length(network) >= 2) AND (length(network) <= 40)))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_asset_check', 'c|CHECK (((length(asset) >= 2) AND (length(asset) <= 20)))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_amount_base_units_check', 'c|CHECK ((amount_base_units > 0))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_status_check', 'c|CHECK ((status = ANY (ARRAY[''PENDING''::text, ''CLAIMED''::text, ''PREPARED''::text, ''SUBMITTED''::text, ''CONFIRMING''::text, ''CONFIRMED''::text, ''RETRYABLE''::text, ''REVIEW_REQUIRED''::text, ''FAILED_PERMANENT''::text])))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_pkey', 'p|PRIMARY KEY (id)'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_payout_obligation_id_key', 'u|UNIQUE (payout_obligation_id)'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_attempt_count_check', 'c|CHECK ((attempt_count >= 0))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_max_attempts_check', 'c|CHECK (((max_attempts >= 1) AND (max_attempts <= 10)))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_failure_count_check', 'c|CHECK ((failure_count >= 0))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_max_failures_check', 'c|CHECK (((max_failures >= 1) AND (max_failures <= 50)))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_last_error_code_check', 'c|CHECK (((last_error_code IS NULL) OR (length(last_error_code) <= 120)))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_last_error_class_check', 'c|CHECK ((last_error_class = ANY (ARRAY[''RETRYABLE''::text, ''PERMANENT''::text, ''REVIEW''::text, ''WAITING''::text])))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_one_obligation', 'c|CHECK ((((obligation_type = ANY (ARRAY[''HELPER_PAYOUT''::text, ''REFERRAL_PAYOUT''::text])) AND (payout_obligation_id IS NOT NULL) AND (service_refund_id IS NULL)) OR ((obligation_type = ''REFUND''::text) AND (service_refund_id IS NOT NULL) AND (payout_obligation_id IS NULL))))'),
    ('202609270015', 'constraint', 'money_movement_jobs.money_movement_jobs_service_refund_id_fkey', 'f|FOREIGN KEY (service_refund_id) REFERENCES service_refunds(id) ON DELETE RESTRICT'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_attempt_number_check', 'c|CHECK ((attempt_number >= 1))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_provider_check', 'c|CHECK ((provider ~ ''^[A-Z0-9_]{2,40}$''::text))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_network_check', 'c|CHECK (((length(network) >= 2) AND (length(network) <= 40)))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_asset_check', 'c|CHECK (((length(asset) >= 2) AND (length(asset) <= 20)))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_amount_base_units_check', 'c|CHECK ((amount_base_units > 0))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_destination_check', 'c|CHECK (((length(destination) >= 8) AND (length(destination) <= 200)))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_external_id_check', 'c|CHECK (((length(external_id) >= 8) AND (length(external_id) <= 200)))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_signed_payload_check', 'c|CHECK (((signed_payload IS NULL) OR (length(signed_payload) <= 4096)))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_state_check', 'c|CHECK ((state = ANY (ARRAY[''PREPARED''::text, ''SUBMITTED''::text, ''CONFIRMED''::text, ''FAILED_ONCHAIN''::text, ''EXPIRED_NOT_LANDED''::text])))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_failure_category_check', 'c|CHECK (((failure_category IS NULL) OR (length(failure_category) <= 120)))'),
    ('202609270015', 'constraint', 'money_movement_attempts.money_movement_attempts_terminal_payload', 'c|CHECK (((state = ANY (ARRAY[''PREPARED''::text, ''SUBMITTED''::text])) OR (signed_payload IS NULL)))'),
