    ('policy', 'profiles.profile self or staff read', '202609120001', 'SELECT|{authenticated}|PERMISSIVE|((id = ( SELECT auth.uid() AS uid)) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
