    ('policy', 'technician_profiles.technician visibility', '202609120001', 'SELECT|{authenticated}|PERMISSIVE|((user_id = ( SELECT auth.uid() AS uid)) OR (verification_status = ''APPROVED''::document_status) OR ( SELECT security.has_role(ARRAY[''ADMIN''::app_role, ''STAFF''::app_role]) AS has_role))|'),
